(1143, NULL, 'BENZOYLECGONINE-COCAINE METABOLITE > Cutoff', NULL, 'Detection Window 3-5 days', NULL, 'Benzoylecgonine is a metabolite of cocaine. Presence of benzoylecgonine indicates use of cocaine. ILLICIT', NULL),
(1144, NULL, 'BUPRENORPHINE > Cutoff', 'Cutoff', 'Detection Window 4-5 days', NULL, 'Presence of buprenorphine indicates use of buprenorphine-containing drugs (e.g. Suboxone and Buprenex). Buprenorphine is metabolized to norbuprenorphine.', NULL),
