(1148, NULL, 'CLONAZEPAM > Cutoff', 'Cutoff', 'Detection window 5-7 days or 6 weeks if > 1 year use', NULL, '7 Amino clonazepam is a metabolite of clonazepam, and its presence indicates use of a clonazepam-containing drug.', NULL),
(1149, NULL, 'CODEINE > Cutoff', 'Cutoff', 'Detection Window 2-3 days', NULL, 'Codeine is not a recognized metabolite of other opiates and its presence indicates use of a codeine-containing drug. Codeine is metabolized to morphine. Other minor metabolites include hydrocodone, hydromorphone and dihydrocodeine. Use of heroin is indicated when 1) both codeine and morphine are detected in urine; 2) morphine concentration is >10,000 ng/mL; and 3) morphine-to-codeine FIX', NULL),
(1150, NULL, 'DESIPRAMINE > Cutoff', 'Cutoff', 'Detection window 3-5 days', NULL, 'Presence of Desipramine indicates use of a  Desipramine (Norpramin) containing drug .', NULL),
(1151, NULL, 'EDDP > Cutoff', 'Cutoff', 'Detection Window 3-5 Days', NULL, 'EDDP (2-ethylidene-1,5-dimethyl-3,3-diphenylpyrrolidine)is a metabolite of methadone, and its presence', NULL),
(1152, NULL, 'FENTANYL > Cutoff', 'Cutoff', 'Detection Window 3-4 days', NULL, 'Presence of fentanyl indicates use of a fentanyl containing drug. Fentanyl is metabolized to norfentanyl.', NULL),
(1153, NULL, 'FLURAZEPAM > Cutoff', 'Cutoff', 'Detection Window 5-7 days or 6 weeks if > 1 year use', NULL, 'Presence of Flurazepam indicates use of a  Flurazepam (Dalmane) containing drug .', NULL),
(1154, NULL, 'GABAPENTIN > Cutoff', 'Cutoff', 'Detection Window 1-4 days', NULL, 'Presence of Gabapentin  indicates use of a Gabapentin (Neurontin) containing drug .', NULL),
(1155, NULL, 'HYDROCODONE > Cutoff', 'Cutoff', 'Detection Window 2-4 days', NULL, 'Hydrocodone may arise from hydrocodone containing drugs or by metabolism of dihydrocodeine.Hydrocodone is metabolized to hydromorphone and dihydrocodeine', NULL),
(1156, NULL, 'HYDROMORPHONE > Cutoff', 'Cutoff', 'Detection Window 2-4 days', NULL, 'Hydromorphone may arise from hydromorphone-containing drugs or by metabolism of morphine and hydrocodone.', NULL),
(1157, NULL, 'HYDROXYALPRAZOLAM > Cutoff', 'Cutoff', 'Detection window 5-7 days or 6 weeks if > 1 year use', NULL, 'Hydroxyalprazolam is a metabolite of Alprazolam, and its presence indicates use of a Alprazolam-containing drug.', NULL),
(1158, NULL, 'IMIPRAMINE > Cutoff', 'Cutoff', 'Detection Window 3 days', NULL, 'Presence indicates use of imipramine', NULL),
(1159, NULL, 'KETAMINE > Cutoff', 'Cutoff', 'Detection window 5-6 days', NULL, 'Presence of Ketamine indicates use of a  Ketamine (Ketalart) containing drug .', NULL),
