(1162, NULL, 'MEPROBAMATE > Cutoff', NULL, 'Detection window 1-2 days', NULL, 'Presence of Meprobamate indicates use of a  Meprobamate (Milltown) containing drug . Or by metabolisim of Carisoprodol.', NULL),
(1163, NULL, 'METHADONE > Cutoff', 'Cutoff', 'Detection Window 3-5 days', NULL, 'Presence of methadone indicates use of a methadone-containing drug. Methadone is metabolized to EDDP. The absence of EDDP and presence of methadone in a urine specimen very likely indicate adulteration by direct addition of methadone to the urine specimen.', NULL),
(1164, NULL, 'METHYLPHENIDATE > Cutoff', 'Cutoff', 'Detection Window 3-5 days', NULL, 'Methylphenidate may arise from Methylphenidate containing  drugs (eg. Ritalin) .', NULL),
(1165, NULL, 'MORPHINE > Cutoff', 'Cutoff', 'Detection Window 2-4 days', NULL, 'Morphine may arise from morphine-containing drugs, poppy seeds or by metabolism of codeine and heroin.Morphine is metabolized to hydromorphone.', NULL),
(1166, NULL, 'NORBUPRENORPHINE > Cutoff', 'Cutoff', 'Detection Window 4-5 days', NULL, 'Buprenorphine is metabolized to norbuprenorphine. Presence of buprenorphine indicates use of buprenorphine-containing drugs (e.g. Suboxone and Buprenex).', NULL),
(1167, NULL, 'NORDIAZEPAM > Cutoff', 'Cutoff', 'Detection Window 5-7 days or 6 weeks if > 1 year use', NULL, 'Nordiazepam is a metabolite of chlorodiazepoxide (Librium), clorazepate (Tranxene), diazepam,, and its presence indicates use of a chlorodiazepoxide (Librium), clorazepate (Tranxene), diazepam, containing drug.', NULL),
(1168, NULL, 'NORFENTANYL > Cutoff', 'Cutoff', 'Detection Window 3-4 days', NULL, 'Norfentanyl is a metabolite of fentanyl, and its presence indicates use of a fentanyl-containing drug.', NULL),
(1169, NULL, 'NORTRIPTYLINE > Cutoff', 'Cutoff', 'Detection window 3-5 days', NULL, 'Presence of Nortriptyline indicates use of a Nortriptyline (Pamelor) containing drug .', NULL),
(1170, NULL, 'OXAZEPAM > Cutoff', 'Cutoff', 'Detection Window 5-7 days or 6 weeks if > 1 year use', NULL, 'Presence of Oxazepam indicates use of a  Oxazepam (Serax) containing drug . Or by metabolisim of nordiazepam and temazepam.', NULL),
(1171, NULL, 'OXYCODONE > Cutoff', 'Cutoff', 'Detection Window 2-4 days', NULL, 'Oxycodone is not a recognized metabolite of other opiates and its presence indicates use of an oxycodone containing drug. Oxycodone is metabolized to oxymorphone', NULL),
