(686, NULL, 'BUPRENORPHINE > Cutoff', 'Cutoff', 'Detection Window 4-5 days', 'Cutoff', 'Presence of buprenorphine indicates use of buprenorphine-containing drugs (e.g. Suboxone and Buprenex). Buprenorphine is metabolized to norbuprenorphine.', 'Base Logic for report 141121.xlsx'),
(687, NULL, 'NORBUPRENORPHINE > Cutoff', 'Cutoff', 'Detection Window 4-5 days', 'Cutoff', 'Buprenorphine is metabolized to norbuprenorphine. Presence of buprenorphine indicates use of buprenorphine-containing drugs (e.g. Suboxone and Buprenex). ', 'Base Logic for report 141121.xlsx'),
(688, NULL, 'METHADONE > Cutoff', 'Cutoff', 'Detection Window 3-5 days', 'Cutoff', 'Presence of methadone indicates use of a methadone-containing drug. Methadone is metabolized to EDDP. The absence of EDDP and presence of methadone in a urine specimen very likely indicate adulteration by direct addition of methadone to the urine specimen.', 'Base Logic for report 141121.xlsx'),
(689, NULL, 'EDDP > Cutoff', 'Cutoff', 'Detection Window 3-5 Days', 'Cutoff', 'EDDP (2-ethylidene-1,5-dimethyl-3,3-diphenylpyrrolidine)is a metabolite of methadone, and its presence ', 'Base Logic for report 141121.xlsx'),
(690, NULL, 'FENTANYL > Cutoff', 'Cutoff', 'Detection Window 3-4 days', 'Cutoff', 'Presence of fentanyl indicates use of a fentanyl containing drug. Fentanyl is metabolized to norfentanyl.', 'Base Logic for report 141121.xlsx'),
(691, NULL, 'NORFENTANYL > Cutoff', 'Cutoff', 'Detection Window 3-4 days', 'Cutoff', 'Norfentanyl is a metabolite of fentanyl, and its presence indicates use of a fentanyl-containing drug.', 'Base Logic for report 141121.xlsx'),
(692, NULL, 'TRAMADOL > Cutoff', 'Cutoff', 'Detection Window 2-4 Days', 'Cutoff', 'Presence of tramadol indicates use of a tramadol containing drug (Ultram). Tramadol is metabolized to O-Desmethyltramadol.', 'Base Logic for report 141121.xlsx'),
(693, NULL, 'ALPRAZOLAM > Cutoff', 'Cutoff', 'Detection window 5-7 days or 6 weeks if > 1 year use', 'Cutoff', 'Presence of Alprazolam indicates use of a Alprazolam containing drug. Alprazolam is metabolized to Hydroxyalprazolam.', 'Base Logic for report 141121.xlsx'),
(694, NULL, 'HYDROXYALPRAZOLAM > Cutoff', 'Cutoff', 'Detection window 5-7 days or 6 weeks if > 1 year use', 'Cutoff', 'Hydroxyalprazolam is a metabolite of Alprazolam, and its presence indicates use of a Alprazolam-containing drug.', 'Base Logic for report 141121.xlsx'),
(695, NULL, '7 AMINO CLONAZAPAM > Cutoff', 'Cutoff', 'Detection window 5-7 days or 6 weeks if > 1 year use', 'Cutoff', '7 Amino clonazepam is a metabolite of clonazepam, and its presence indicates use of a clonazepam-containing drug.', 'Base Logic for report 141121.xlsx'),
(696, NULL, 'BENZOYLECGONINE > Cutoff', 'Cutoff', 'Detection Window 3-5 days', 'Cutoff', 'Benzoylecgonine is a metabolite of cocaine. Presence of benzoylecgonine indicates use of cocaine. ILLICIT', 'Base Logic for report 141121.xlsx'),
(697, NULL, 'PCP > Cutoff', 'Cutoff', 'Detection window 5-7 days or 30 days with heavy use', 'Cutoff', 'Presence of PCP  indicates the use of  Phencyclidine. ILLICIT', 'Base Logic for report 141121.xlsx');
